const WORDMARK_DOT = "M1792.2 -659.5a66.8 66.8 0 1 0 133.6 0a66.8 66.8 0 1 0 -133.6 0Z";

/** The hexagon on its own - the favicon, and anywhere space is tight. */
export function LogoMark({ size = 34, className = "" }) {
  const id = useId().replace(/:/g, "");
  return (
    <svg
      className={"logo-mark " + className}
      width={size}
      height={size}
      viewBox="0 0 64 64"
      aria-hidden="true"
    >
      <defs>
        <linearGradient id={"hex" + id} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0" stopColor="#ffc62e" />
          <stop offset="1" stopColor="#f5a800" />
        </linearGradient>
      </defs>
      <path
        d="M32 6 L54.5 19 L54.5 45 L32 58 L9.5 45 L9.5 19 Z"
        fill={"url(#hex" + id + ")"}
        stroke={"url(#hex" + id + ")"}
        strokeWidth="7"
        strokeLinejoin="round"
      />
      <path
        d="M22 45 L32 18.5 L42 45"
        fill="none"
        stroke="#ffffff"
        strokeWidth="7"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

/** Hexagon and wordmark together. `size` is the hexagon's height in px. */
export default function Logo({ size = 34, className = "" }) {
  return (
    <span className={"logo " + className} role="img" aria-label="Altrium">
      <LogoMark size={size} />
      <svg
        className="logo-word"
        height={Math.round(size * 0.62)}
        viewBox={WORDMARK_VIEWBOX}
        aria-hidden="true"
      >
        <path d={WORDMARK_LETTERS} fill="currentColor" />
        <path d={WORDMARK_DOT} fill="#fbb401" />
      </svg>
    </span>
  );
}
